/// RCU_INITIALIZER() - statically initialize an RCU-protected global variable
/// @v: The value to statically initialize with.
macro_rules! RCU_INITIALIZER {
($v:expr) => {
$v
};
}

macro_rules! RCU_LOCKDEP_WARN__2 {
($c:expr) => {
while false && $c {
}
};
}

macro_rules! RCU_LOCKDEP_WARN {
($c:expr) => {
loop {
let __v: bool = false && $c;
if !__v {
break;
}
}
};
}

macro_rules! RELOC_HIDE {
($ptr:expr, $off:expr) => {
(($ptr) as u64).wrapping_add(($off) as u64) as *mut ()
};
}

macro_rules! SKB_DATA_ALIGN {
($X:expr) => {
ALIGN!($X, 64i32)
};
}

macro_rules! SKB_EXT_ERR {
($skb:expr) => {
(unsafe { (*$skb).cb.as_mut_ptr() as *mut u8 }) as *mut sock_exterr_skb
};
}

/// return minimum truesize of one skb containing X bytes of data
macro_rules! SKB_TRUESIZE__2 {
($X:expr) => {
$X.wrapping_add(SKB_DATA_ALIGN!(core::mem::size_of::<sk_buff>() as u64)).wrapping_add(SKB_DATA_ALIGN!(core::mem::size_of::<skb_shared_info>() as u64))
};
}

macro_rules! SOCK_SKB_CB {
($__skb:expr) => {
unsafe { (*$__skb).cb.as_mut_ptr() as *mut u8 }.wrapping_offset((core::mem::size_of::<[u8; 48]>() as u64).wrapping_sub(core::mem::size_of::<sock_skb_cb>() as u64) as isize) as *mut sock_skb_cb
};
}

