fn numa_drop_read(ndc: *const numa_drop_counters) -> i32 {
atomic_read(unsafe { core::ptr::addr_of!((*ndc).drops0) }).wrapping_add(atomic_read(unsafe { core::ptr::addr_of!((*ndc).drops1) }))
}

fn numa_drop_add(ndc: *mut numa_drop_counters, val: i32) {
let n: i32 = numa_node_id() % 2;
if n != 0 {
atomic_add(val, unsafe { core::ptr::addr_of_mut!((*ndc).drops1) });
} else {
atomic_add(val, unsafe { core::ptr::addr_of_mut!((*ndc).drops0) });
}
}

fn numa_drop_reset(ndc: *mut numa_drop_counters) {
atomic_set(unsafe { core::ptr::addr_of_mut!((*ndc).drops0) }, 0i32);
atomic_set(unsafe { core::ptr::addr_of_mut!((*ndc).drops1) }, 0i32);
}

