/// created and the current process has the capability @cap in all user
/// namespaces.
#[unsafe(no_mangle)]
#[unsafe(link_section = ".text.slate_distinct.sock.sk_capable")]
extern "C" fn sk_capable(sk: *const sock, cap: i32) -> bool {
sk_ns_capable(sk, unsafe { core::ptr::addr_of_mut!(init_user_ns) }, cap)
}

